{
  "scenarios": [
    {
      "id": "M08-01",
      "category": "搬家旅行与生活环境变化",
      "turns": [
        {
          "user": "我上个月刚把家从喧闹的市中心搬到了城郊的安静小区，因为那里离我新工作的地方更近，而且空气也更好一些。",
          "assistant": "收到，已记录您上个月搬家至城郊新居的情况。"
        },
        {
          "user": "补充一下，这次搬家其实是因为我在新公司附近租到了这套房子，所以从市中心搬走是上周正式完成的。",
          "assistant": "明白，已更新您上周完成从市中心搬至新公司附近城郊的记录。"
        }
      ],
      "queries": [
        {
          "id": "M08-01-Q1",
          "query": "请告诉我这位患者最近一次更换居住地的具体时间以及搬往了哪里？",
          "expected_facts": [
            "患者于上周正式完成了搬家。",
            "患者从市中心搬到了城郊的新小区。",
            "搬家原因是为了靠近新工作地点。"
          ],
          "required_groups": [
            ["上周", "上个月"],
            ["城郊", "郊区", "新小区"],
            ["市中心", "市区"]
          ]
        },
        {
          "id": "M08-01-Q2",
          "query": "患者之前住在哪里，现在又住在哪里，这次变动发生在什么时候？",
          "expected_facts": [
            "患者之前居住在市中心。",
            "患者现在居住在城郊的新小区。",
            "这次变动发生在上周。"
          ],
          "required_groups": [
            ["之前", "原来", "以前"],
            ["现在", "目前", "当前"],
            ["上周", "最近"]
          ]
        }
      ]
    },
    {
      "id": "M08-02",
      "category": "搬家旅行与生活环境变化",
      "turns": [
        {
          "user": "去年夏天我独自去云南旅行了一周，那是我第一次去那么远的地方，主要是在大理和丽江停留，风景很美。",
          "assistant": "好的，已记录您去年夏天独自前往云南旅行的经历。"
        },
        {
          "user": "更正一下，那次旅行其实是和一位老朋友一起去的，我们是在去年六月出发的，在大理住了五天。",
          "assistant": "收到，已更正为去年六月与朋友同行，并在大理停留五天。"
        }
      ],
      "queries": [
        {
          "id": "M08-02-Q1",
          "query": "患者去年夏天的旅行是独自一人还是有人陪同，具体去了哪些城市？",
          "expected_facts": [
            "患者去年夏天的旅行是与一位老朋友同行的。",
            "患者去了大理和丽江。",
            "旅行出发时间是去年六月。"
          ],
          "required_groups": [
            ["老朋友", "朋友", "同伴"],
            ["大理", "丽江"],
            ["去年六月", "去年夏天"]
          ]
        },
        {
          "id": "M08-02-Q2",
          "query": "请确认患者那次云南之行的具体行程细节和同行人员情况。",
          "expected_facts": [
            "患者在大理停留了五天。",
            "患者是与朋友一起前往云南的。",
            "旅行发生在去年六月。"
          ],
          "required_groups": [
            ["五天", "五天时间"],
            ["朋友", "同伴"],
            ["去年六月"]
          ]
        }
      ]
    },
    {
